// Format all results into email body
const items = $input.all();
const date = new Date().toLocaleDateString('vi-VN');

let emailBody = `<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; }
    h1 { color: #333; }
    h2 { color: #666; margin-top: 30px; }
    table { border-collapse: collapse; width: 100%; margin: 20px 0; }
    th { background-color: #4CAF50; color: white; padding: 12px; text-align: left; }
    td { border: 1px solid #ddd; padding: 8px; }
    tr:nth-child(even) { background-color: #f2f2f2; }
    .sql-block { background-color: #f4f4f4; padding: 10px; border-radius: 5px; font-family: monospace; white-space: pre-wrap; }
    .summary { background-color: #e7f3fe; padding: 15px; border-left: 4px solid #2196F3; margin: 20px 0; }
  </style>
</head>
<body>
  <h1>📊 Báo cáo Doanh số Hàng ngày</h1>
  <p><strong>Ngày:</strong> ${date}</p>
  <div class="summary">
    <strong>Tóm tắt:</strong> Báo cáo bao gồm ${items.length} phân tích.
  </div>
`;

let totalRevenue = 0;
let totalOrders = 0;

items.forEach((item, index) => {
  const question = $('Split Questions').item(index).json.report_questions;
  const sqlResponse = $('Generate SQL').item(index).json;
  const runResponse = item.json;

  emailBody += `<h2>📌 ${question}</h2>`;
  emailBody += `<div class="sql-block">${sqlResponse.text}</div>`;

  if (runResponse.type === 'df') {
    const data = JSON.parse(runResponse.df);

    if (data.length > 0) {
      // Create HTML table
      emailBody += '<table>';

      // Header
      emailBody += '<tr>';
      Object.keys(data[0]).forEach(key => {
        emailBody += `<th>${key}</th>`;
      });
      emailBody += '</tr>';

      // Rows (max 20)
      data.slice(0, 20).forEach(row => {
        emailBody += '<tr>';
        Object.values(row).forEach(value => {
          emailBody += `<td>${value !== null ? value : 'N/A'}</td>`;
        });
        emailBody += '</tr>';
      });

      emailBody += '</table>';

      if (data.length > 20) {
        emailBody += `<p><em>... và ${data.length - 20} kết quả khác</em></p>`;
      }
    } else {
      emailBody += '<p><em>Không có dữ liệu</em></p>';
    }
  } else if (runResponse.type === 'sql_error') {
    emailBody += `<p style="color: red;"><strong>Lỗi:</strong> ${runResponse.error}</p>`;
  }
});

emailBody += `
  <hr>
  <p style="color: #999; font-size: 12px;">
    Báo cáo tự động được tạo bởi Vanna AI SQL Assistant<br>
    Thời gian tạo: ${new Date().toLocaleString('vi-VN')}
  </p>
</body>
</html>`;

const config = $('Set Report Config').first().json;

return {
  json: {
    to: config.email_to,
    subject: config.email_subject,
    html: emailBody
  }
};
